import{_ as t,c as s,o as l,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"《周易折中》简介","description":"周易折中 - 《周易折中》简介","frontmatter":{"title":"《周易折中》简介","description":"周易折中 - 《周易折中》简介"},"headers":[],"relativePath":"zh/classics/zhezhong/001.md","filePath":"zh/classics/zhezhong/001.md"}'),r={name:"zh/classics/zhezhong/001.md"};function o(c,a,i,p,d,h){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"《周易折中》简介",tabindex:"-1"},[n("《周易折中》简介 "),e("a",{class:"header-anchor",href:"#《周易折中》简介","aria-label":"Permalink to “《周易折中》简介”"},"​")],-1),e("p",null,"《周易折中》是清代康熙朝大臣李光地所著的一部易学著作，也是康熙皇帝敕命主持撰写的重要文献。该书以通俗易懂的语言，遍采诸家大儒之说，详加考订，阐幽发微，是学《易》、研《易》者的案头必备之书。",-1),e("p",null,"在内容上，《周易折中》兼讲象数与义理，集汉易、宋易之大成。李光地极为推崇朱熹、程颐的注解，认为朱熹《周易本义》“独得《易》之本义”，程氏《易传》诠释“《易》之义理为详”。 （朱熹之学在历史上有一定争议） 因此，在解释经文时，他首先列出《本义》，其次是《程传》，然后再辅以“集说”、“附录”、“总论”及“案”语等，以全面展示各家之说。此外，书中还详细探讨了先后天八卦的方位，这种探讨对于易学研究具有重要的指导意义。",-1),e("p",null,"在编纂背景上，康熙皇帝深知李光地“素学有本，易理精详”，因此选择他作为总裁修订此书。李光地仅用两年时间就主持完成了《折中》的编撰工作，这体现了他的深厚学术功底和卓越贡献。",-1),e("p",null,"从影响上来看，《周易折中》是研究清代易学最重要的典籍之一，对于后来的易学研究和经学发展具有重要的意义。它推动了中国传统文化的发展和繁荣，使得更多的人能够理解和掌握易学的精髓和义理。在今天的社会中，我们仍然可以从《周易折中》中汲取智慧和启示。",-1),e("p",null,"请注意，为了方便阅读查找，录入内容并没有采取原来的分卷次序，详情可查看四库全书。",-1),e("p",null,"总的来说，《周易折中》是一部集合多家思想、深入浅出的易学著作，对于易学研究者和爱好者来说具有重要的参考和借鉴价值。",-1)])])}const _=t(r,[["render",o]]);export{m as __pageData,_ as default};
